@app.post("/api/admin/shutdown")
async def admin_shutdown(request: Request) -> JSONResponse:
    """Stop the StreamLink server.

    Sends SIGTERM to every uvicorn process running our `main:app` (the HTTP
    process on port 80 and, when SSL certs exist, the HTTPS process on port
    443). The launcher (run.py) is blocked on the HTTP uvicorn via
    subprocess.run, so once that exits its finally block also cleans up the
    HTTPS sibling — see run.py:861.
    """
    _require_admin(request)

    async def _kill_uvicorns() -> None:
        # Brief delay so this HTTP response can flush back to the client
        # before we tear our own process down.
        await asyncio.sleep(0.5)
        me = os.getpid()
        targets: list[psutil.Process] = []
        for proc in psutil.process_iter(["pid", "name", "cmdline"]):
            try:
                cmdline = proc.info.get("cmdline") or []
                joined = " ".join(cmdline)
                if "uvicorn" in joined and "main:app" in joined:
                    targets.append(proc)
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
        # Signal siblings first, then self last, so the admin process stays
        # alive long enough to send the others.
        siblings = [p for p in targets if p.pid != me]
        selves   = [p for p in targets if p.pid == me]
        for p in siblings + selves:
            try:
                p.send_signal(signal.SIGTERM)
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                continue
        # Hard-exit fallback in case uvicorn ignores SIGTERM for some reason.
        await asyncio.sleep(3.0)
        os._exit(0)

    asyncio.create_task(_kill_uvicorns())
    return JSONResponse({"ok": True, "message": "Server shutting down…"})


@app.post("/api/admin/reboot")
async def admin_reboot(request: Request) -> JSONResponse:
    """Reboot the host machine immediately.

    This restarts the whole computer, not just the web server. For the server to
    come back automatically the host needs auto-login + the StreamLink system
    service installed (`run.py --install`); see README. Used as a hard reset for
    a wedged Jackett. The reboot fires ~0.5 s after this response flushes.
    """
    _require_admin(request)
    asyncio.create_task(_reboot_machine())
    return JSONResponse({"ok": True, "message": "Rebooting host machine…"})


# ── Log download ──────────────────────────────────────────────────────────────
# Operators frequently need the server's rotating log files (hls.log,
# streamlink_app.log, streamlink.err, …) to diagnose a remote box where SSH
# isn't set up. These admin endpoints expose the contents of LOG_DIR read-only:
# a directory listing + per-file download + a bundled zip of everything. Path
# traversal is blocked by resolving the requested name against LOG_DIR and
# refusing anything that escapes it.

def _safe_log_path(name: str) -> Path:
    """Resolve `name` against LOG_DIR, refusing traversal/absolute paths.

    Raises HTTPException on any attempt to escape LOG_DIR or read a non-file.
    """
    if not name or "/" in name or "\\" in name or name in (".", ".."):
        raise HTTPException(400, "Invalid log filename.")
    candidate = (LOG_DIR / name).resolve()
    try:
        candidate.relative_to(LOG_DIR.resolve())
    except ValueError:
        raise HTTPException(400, "Log file is outside the logs directory.")
    if not candidate.exists() or not candidate.is_file():
        raise HTTPException(404, "Log file not found.")
    return candidate


def _is_prior_log(name: str) -> bool:
    """A prior-run log archive (`logs_old_<timestamp>.zip`), produced by
    `_archive_old_logs` at startup after a version update. These are historical
    and kept distinct from the current run's logs in the admin UI + bundles."""
    return name.startswith("logs_old_")


def _build_logs_zip(files: list[Path]) -> str:
    """Build a seekable temp ZIP of `files` and return its path.

    The ZIP is written to a *seekable* temp file rather than streamed through a
    pipe. A streamed (non-seekable) ZIP forces `zipfile` to emit data
    descriptors (general-purpose bit 3) with zero CRC/sizes in each local
    header; macOS/7-Zip read the central directory so they cope, but **Windows
    Explorer's built-in extractor reads the local headers and rejects the
    archive as "invalid."** Writing to a seekable file lets `zipfile` back-patch
    real local headers, so Windows (our primary target) can extract it. See
    docs/GOTCHAS.md.

    Each member is read via its own handle so a log that another process is
    actively appending to (e.g. `streamlink_service.log`, held open by the
    service-wrapper process) is still captured.
    """
    fd, tmp_path = tempfile.mkstemp(prefix="streamlink-logs-", suffix=".zip")
    try:
        with os.fdopen(fd, "wb") as wf, \
                zipfile.ZipFile(wf, "w", zipfile.ZIP_DEFLATED) as zf:
            for p in files:
                try:
                    with open(p, "rb") as src:
                        data = src.read()
                except OSError:
                    continue
                zf.writestr(p.name, data)
    except Exception:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass
        raise
    return tmp_path


@app.get("/api/admin/logs")
async def admin_list_logs(request: Request) -> JSONResponse:
    """List every file in LOG_DIR with size + mtime (newest first)."""
    _require_admin(request)
    entries = []
    if LOG_DIR.exists():
        for p in LOG_DIR.iterdir():
            if not p.is_file():
                continue
            try:
                st = p.stat()
            except OSError:
                continue
            entries.append({
                "name":   p.name,
                "bytes":  st.st_size,
                "mtime":  int(st.st_mtime),
                "prior":  _is_prior_log(p.name),
            })
    entries.sort(key=lambda e: e["mtime"], reverse=True)
    return JSONResponse({"log_dir": str(LOG_DIR), "files": entries})


@app.get("/api/admin/logs/_bundle")
async def admin_download_logs_bundle(request: Request) -> FileResponse:
    """Download a ZIP of the **current run's** log files in LOG_DIR.

    Prior-run archives (`logs_old_*.zip`) are deliberately excluded — they're
    already individual zips and are bundled separately by `_prior-bundle`, so
    "Download All" stays a focused snapshot of the logs that matter for the
    issue at hand instead of re-zipping every historical archive.

    Path is `_bundle` (underscore prefix) so it can't collide with a real log
    filename — `_safe_log_path` rejects names containing slashes anyway, but
    matching against the literal `_bundle` route ensures the per-file handler
    never sees this name.
    """
    _require_admin(request)
    files: list[Path] = []
    if LOG_DIR.exists():
        for p in LOG_DIR.iterdir():
            if p.is_file() and not _is_prior_log(p.name):
                files.append(p)
    if not files:
        raise HTTPException(404, "No log files to download.")

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    zip_name = f"streamlink-logs-{stamp}.zip"

    tmp_path = await asyncio.to_thread(_build_logs_zip, files)

    def _cleanup() -> None:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass

    return FileResponse(
        tmp_path,
        media_type="application/zip",
        filename=zip_name,
        headers={"Content-Disposition": f'attachment; filename="{zip_name}"'},
        background=BackgroundTask(_cleanup),
    )


@app.get("/api/admin/logs/_prior-bundle")
async def admin_download_prior_logs_bundle(request: Request) -> FileResponse:
    """Download a ZIP of every prior-run log archive (`logs_old_*.zip`).

    Each archive is itself a zip of one previous version's logs (produced by
    `_archive_old_logs` at startup after an update). They're excluded from the
    main `_bundle` and gathered here on demand so an operator can pull the full
    history in one click without downloading each archive individually.

    Registered before the `{name}` catch-all so the literal `_prior-bundle`
    route wins. See `_build_logs_zip` for the Windows-extractable ZIP rationale.
    """
    _require_admin(request)
    files: list[Path] = []
    if LOG_DIR.exists():
        for p in LOG_DIR.iterdir():
            if p.is_file() and _is_prior_log(p.name):
                files.append(p)
    if not files:
        raise HTTPException(404, "No prior logs to download.")

    stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
    zip_name = f"streamlink-prior-logs-{stamp}.zip"

    tmp_path = await asyncio.to_thread(_build_logs_zip, files)

    def _cleanup() -> None:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass

    return FileResponse(
        tmp_path,
        media_type="application/zip",
        filename=zip_name,
        headers={"Content-Disposition": f'attachment; filename="{zip_name}"'},
        background=BackgroundTask(_cleanup),
    )


@app.get("/api/admin/logs/{name}")
async def admin_download_log(request: Request, name: str) -> FileResponse:
    """Download one file from LOG_DIR by name. Forces attachment disposition.

    The file is snapshotted to a temp copy before being served. Logs such as
    `streamlink_service.log` are held open by another process (the
    service-wrapper) and grow continuously; serving a stable copy sidesteps the
    read-while-appended races that otherwise made that log fail to download.
    """
    _require_admin(request)
    path = _safe_log_path(name)

    def _snapshot() -> str:
        fd, tmp_path = tempfile.mkstemp(prefix="streamlink-log-", suffix=".log")
        try:
            with os.fdopen(fd, "wb") as dst, open(path, "rb") as src:
                shutil.copyfileobj(src, dst, 1024 * 1024)
        except OSError:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise HTTPException(500, "Could not read log file.")
        return tmp_path

    tmp_path = await asyncio.to_thread(_snapshot)

    def _cleanup() -> None:
        try:
            os.unlink(tmp_path)
        except OSError:
            pass

    return FileResponse(
        tmp_path,
        media_type="text/plain; charset=utf-8",
        filename=path.name,
        headers={"Content-Disposition": f'attachment; filename="{path.name}"'},
        background=BackgroundTask(_cleanup),
    )


@app.delete("/api/admin/logs")
async def admin_clear_logs(request: Request) -> JSONResponse:
    """Clear every file in LOG_DIR.

    Active rotating handlers (`streamlink_app.log`, `hls.log`, `vitals.log`,
    `access.log`, `uvicorn.log`) are **truncated
    in-place via the handler's stream** rather than deleted — on Windows you
    can't unlink a file that the running process has open for writing, and even
    on POSIX a delete would leave the FD valid but disconnected from any
    on-disk file so subsequent writes would vanish until the next restart.
    Truncating via `handler.stream.truncate(0)` keeps logging fully functional;
    new lines append from offset 0.

    Non-active files (rotated `.1`/`.2`/`.3` siblings, plus the
    launchd/systemd-written `streamlink.err`) are unlinked. If unlink fails
    (e.g. service still has an exclusive write handle on Windows), we fall back
    to a write-mode truncate and continue.
    """
    _require_admin(request)

    cleared: list[str] = []
    errors:  list[dict] = []
    active_basenames: set[str] = set()

    # 1) Truncate the live rotating-file handlers via their own streams so we
    #    don't race the logging thread.
    # Every logger that holds a live RotatingFileHandler. The diagnostics
    # loggers (vitals) and uvicorn's own (access.log, uvicorn.log) must be in
    # here too: anything left out falls through to the unlink branch below,
    # which on Windows can't remove a file this process holds open for writing.
    for logger_name in ("streamlink", "streamlink.hls", "streamlink.vitals",
                        "uvicorn.access", "uvicorn.error"):
        lg = logging.getLogger(logger_name)
        for h in lg.handlers:
            if not isinstance(h, RotatingFileHandler):
                continue
            try:
                base = Path(h.baseFilename).name
                active_basenames.add(base)
                h.acquire()
                try:
                    if h.stream:
                        h.stream.flush()
                        h.stream.seek(0)
                        h.stream.truncate(0)
                finally:
                    h.release()
                cleared.append(base)
            except Exception as e:
                errors.append({"file": Path(h.baseFilename).name, "error": str(e)})

    # 2) Everything else in LOG_DIR — delete; on failure, truncate-and-keep.
    if LOG_DIR.exists():
        for p in LOG_DIR.iterdir():
            if not p.is_file() or p.name in active_basenames:
                continue
            try:
                p.unlink()
                cleared.append(p.name)
                continue
            except OSError:
                pass
            try:
                with open(p, "wb"):
                    pass
                cleared.append(p.name)
            except OSError as e:
                errors.append({"file": p.name, "error": str(e)})

    log.info(
        "Admin cleared logs: %d file(s) cleared, %d error(s).",
        len(cleared), len(errors),
    )
    return JSONResponse({"ok": True, "cleared": cleared, "errors": errors})


@app.get("/api/admin/scheduled-reboot")
async def admin_get_scheduled_reboot(request: Request) -> JSONResponse:
    """Return the scheduled-reboot config + the host's current time in the
    configured timezone (so the UI can show what 'now' looks like there)."""
    _require_admin(request)
    cfg = _scheduled_reboot_cfg(await get_library())
    now = _now_in_tz(cfg["timezone"])
    cfg["now"] = now.strftime("%Y-%m-%d %H:%M %Z").strip()
    return JSONResponse(cfg)


@app.post("/api/admin/scheduled-reboot")
async def admin_set_scheduled_reboot(
    request: Request, body: ScheduledRebootReq,
) -> JSONResponse:
    """Save the scheduled-reboot config. Validates the HH:MM time and clamps both
    the idle window and the catch-up window. Changing the config clears any prior
    `last_fired` guard so a newly-set time can arm today — the catch-up window
    still bounds it, so a save made long after the scheduled time won't trigger
    an immediate reboot."""
    _require_admin(request)

    parts = body.time.split(":")
    try:
        h, m = int(parts[0]), int(parts[1])
        assert 0 <= h <= 23 and 0 <= m <= 59
    except (ValueError, IndexError, AssertionError):
        raise HTTPException(400, "time must be HH:MM (24-hour), e.g. 00:00")

    idle = max(1, min(720, int(body.idle_minutes)))
    catch_up = max(1, min(24, int(body.catch_up_hours)))

    async with mutate_library() as lib:
        sr = lib.setdefault("settings", {}).setdefault("scheduled_reboot", {})
        sr["enabled"]        = bool(body.enabled)
        sr["time"]           = f"{h:02d}:{m:02d}"
        sr["timezone"]       = body.timezone.strip()
        sr["idle_minutes"]   = idle
        sr["catch_up_hours"] = catch_up
        sr["last_fired"]     = ""   # reset guard so the new schedule can arm today

    cfg = _scheduled_reboot_cfg(lib)
    cfg["now"] = _now_in_tz(cfg["timezone"]).strftime("%Y-%m-%d %H:%M %Z").strip()
    return JSONResponse({"ok": True, **cfg})


@app.get("/api/admin/auto-prep")
async def admin_get_auto_prep(request: Request) -> JSONResponse:
    """Return the unified Automatic Stream Prep config (`settings.auto_prep`) plus
    live status: whether the box is idle right now, the bulk pause state, and
    whether prep is actively running."""
    _require_admin(request)
    cfg = _auto_prep_cfg(await get_library())
    in_use = await _machine_in_use(cfg["idle_minutes"] * 60)
    cfg["idle_now"] = not in_use
    cfg["paused"]   = state.prep_paused
    if cfg["mode"] == "always":
        cfg["active"] = bool(state.auto_prep_engaged)
    elif cfg["mode"] == "idle":
        cfg["active"] = bool(state.auto_prep_engaged and not in_use)
    else:
        cfg["active"] = False
    return JSONResponse(cfg)


@app.post("/api/admin/auto-prep")
async def admin_set_auto_prep(request: Request, body: AutoPrepReq) -> JSONResponse:
    """Save the unified Automatic Stream Prep config. Validates `mode` /
    `on_activity` and clamps `idle_minutes` (1–720). Re-derives the trigger on the
    next scheduler tick by resetting the engagement edge flag."""
    _require_admin(request)
    # Reject an unknown mode rather than silently coercing it: falling back to "off"
    # meant a typo'd value came back 200 OK having quietly DISABLED automatic prep.
    # (The sibling /prep-validate endpoint already 400s on bad input.)
    if body.mode not in ("always", "idle", "off"):
        raise HTTPException(400, "mode must be 'always', 'idle' or 'off'.")
    if body.on_activity not in ("soft", "hard"):
        raise HTTPException(400, "on_activity must be 'soft' or 'hard'.")
    mode = body.mode
    on_activity = body.on_activity
    idle_minutes = max(1, min(720, int(body.idle_minutes)))

    async with mutate_library() as lib:
        ap = lib.setdefault("settings", {}).setdefault("auto_prep", {})
        ap["mode"]         = mode
        ap["idle_minutes"] = idle_minutes
        ap["on_activity"]  = on_activity

    # Re-derive "want" fresh against the new config on the next loop tick.
    state.auto_prep_engaged = False

    cfg = _auto_prep_cfg(lib)
    in_use = await _machine_in_use(cfg["idle_minutes"] * 60)
    cfg["idle_now"] = not in_use
    return JSONResponse({"ok": True, **cfg})


